async function invitations(){const base=JSON.parse(fs.readFileSync(path.join(OUT,'completed-save.json')));for(const id of ['merchant','elder']){const{ctx,p}=await session(base);try{await baskets(p);await p.locator('#readNeighbor').click();await p.locator('#gatheringEntry').click();await p.locator('#gatherInvite').click();const before=await resources(p);await p.locator('[data-invite='+id+']').click();await p.locator('#inviteConfirm').click();check(await resources(p)===before,id+' shared invitation spends nothing extra');await snap(p,`phone-memory-invite-${id}-reply.png`);await p.reload();await ready(p);await baskets(p);await p.locator('#readNeighbor').click();await p.locator('#gatheringEntry').click();await p.locator('#gatherInvite').click();check(await p.locator('#inviteConfirm').isDisabled(),id+' invitation stays disabled after reload');await snap(p,`phone-memory-invite-${id}-reloaded.png`);await p.locator('#inviteBack').click();if(await p.locator('.journal-next').isEnabled())await p.locator('.journal-next').click();await snap(p,`phone-journal-invite-${id}-reloaded.png`);}finally{await ctx.close();}}}
async function layouts(){for(const v of [{w:320,h:568},{w:390,h:844},{w:430,h:932},{w:844,h:390},{w:768,h:1024},{w:1024,h:768},{w:1032,h:1376},{w:1376,h:1032},{w:1366,h:600}]){
 const{ctx,p}=await session(read('picnic-base-save.json'),v);try{await picnic(p);await p.locator('[data-serve-person=child]').click();await p.locator('[data-serve-taste=sweet]').click();await controls(p,`${v.w}x${v.h} serving`);await p.locator('#gatherSip').click();await p.locator('#gatherSkip').click();check(await p.evaluate(()=>__farm.state().adventure.gathering.servings.length===1),v.w+' actual portion playable');await snap(p,`layout-meal-${v.w}x${v.h}.png`);}finally{await ctx.close();}
 const f=await session(read('fish-earned-save.json'),v);try{await f.p.evaluate(()=>FarmWorld.visitSite('fishing_dock'));await f.p.locator('#worldFishNotes').click();await f.p.locator('#pondPractice').click();await controls(f.p,v.w+' practice');await f.p.locator('.practice-reel').click();await controls(f.p,v.w+' choose');await f.p.locator('[data-guess]').first().click();await controls(f.p,v.w+' result');await snap(f.p,`layout-pond-${v.w}x${v.h}.png`);}finally{await f.ctx.close();}
}}
async function stores(){for(const v of [{w:430,h:932,dpr:3,name:'iphone'},{w:1032,h:1376,dpr:2,name:'ipad'}]){const{ctx,p}=await session(read('fish-earned-save.json'),v);try{await p.evaluate(()=>FarmWorld.visitSite('fishing_dock'));await p.locator('#worldFishNotes').click();await p.evaluate(()=>Math.random=()=>.99);await p.locator('#pondPractice').click();await p.waitForFunction(()=>document.querySelector('.pond-stage')?.dataset.reel==='active');await p.locator('.practice-reel').click();await auditWater(p,'river_perch',report);await snap(p,v.name+'-25-water-shapes-r20.png',true);}finally{await ctx.close();}}}
async function offline(){const base=read('fish-earned-save.json'),{ctx,p}=await session(base,{w:430,h:932},'allow');try{await p.waitForFunction(()=>navigator.serviceWorker.controller&&sessionStorage.getItem('pixelFarmPwaAutoReloaded'),null,{timeout:45000});await ctx.setOffline(true);await p.reload();await ready(p);await p.evaluate(()=>FarmWorld.visitSite('fishing_dock'));await p.locator('#worldFishNotes').click();await p.locator('#pondPractice').click();await p.waitForFunction(()=>document.querySelector('.pond-stage')?.dataset.reel==='active');check(await p.locator('.pond-effects').getAttribute('data-generated-water')!==null,'new generated water runs offline');await snap(p,'phone-pond-offline-active.png');}finally{await ctx.close();}}
(async()=>{const only=process.argv.find(x=>x.startsWith('--only='))?.split('=')[1];try{const s=await serve();server=s.server;origin=s.origin;browser=await chromium.launch({headless:true});if(only)await({delivery,fishing,serving,'serving-correct':()=>serving(true),invitations,layouts,stores,offline}[only])();else{await delivery();await fishing();await serving();await invitations();await layouts();await stores();await offline();}check(report.errors.length===0,'zero uncaught browser errors');report.status='VERIFIED';}catch(e){report.status='BLOCKED';report.failure=e.stack;console.error(e);process.exitCode=1;}finally{await browser?.close();if(server)await new Promise(r=>server.close(r));const viewportSuffix=process.env.FARM_VIEWPORT_WIDTH?`-${process.env.FARM_VIEWPORT_WIDTH}x${process.env.FARM_VIEWPORT_HEIGHT}`:'';const file=path.join(OUT,'journey'+(only?'-'+only:'')+viewportSuffix+'.json');if(fs.existsSync(file)){const old=JSON.parse(fs.readFileSync(file));if(old.status==='BLOCKED')fs.copyFileSync(file,path.join(OUT,'journey-attempt-'+Date.now()+'.json'));}report.captureAttemptCount=report.captureAttempts.length;report.captureReturnNotReadyCount=report.captureAttempts.filter(a=>a.returnNotReady).length;report.captureRejectedAttemptCount=report.captureAttempts.filter(a=>a.outcome==='REJECTED').length;report.nativeCaptureCount=report.frames.filter(f=>f.nativeCapture!==false).length;report.byteCopyAliasCount=report.frames.filter(f=>f.nativeCapture===false).length;fs.writeFileSync(file,JSON.stringify(report,null,2)+'\n');}})();
